"use client";

import { Portal } from "@chakra-ui/react"

export default {
  title: "Components / Portal",
}

export const PortalBasic = () => (
  <>
    <p>Welcome</p>
    <Portal>This text has been portaled</Portal>
  </>
)

"use client";

import { Portal } from "@chakra-ui/react"
import { useRef } from "react"

export const PortalWithContainer = () => {
  const ref = useRef<HTMLDivElement | null>(null)

  return (
    <>
      <Portal container={ref}>
        <span>This text has been portaled</span>
      </Portal>
      <div ref={ref} />
    </>
  )
}

"use client";

import { Portal } from "@chakra-ui/react"
import Frame from "react-frame-component"

export const PortalWithIframe = () => (
  <Frame>
    <h1>Welcome</h1>
    <Portal>Welcome</Portal>
  </Frame>
)

"use client";

import Example from "@/components/rendyn-libraries/chakra/upstream/examples/portal-basic";
import { ChakraProvider, defaultSystem } from "@chakra-ui/react";

export default function Preview() {

  return <div style={{ width: "100%", maxWidth: "48rem", padding: "1.5rem" }}><ChakraProvider value={defaultSystem}><Example /></ChakraProvider></div>;
}

